import{a2 as a,P as n,Q as s,_ as e}from"./framework-04579a5f.js";const t={},c=e(`<h2 id="player-interface" tabindex="-1"><a class="header-anchor" href="#player-interface" aria-hidden="true">#</a> Player interface</h2><h3 id="fplayer" tabindex="-1"><a class="header-anchor" href="#fplayer" aria-hidden="true">#</a> FPlayer</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token class-name">FPlayer</span> fplayer <span class="token operator">=</span> <span class="token class-name">FPlayer</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Creating <code>fplayer</code> also brings up the native player on Android/iOS/macOS/Windows/OpenHarmony and the <code>fplayercore</code> C layer underneath. You have to release those resources with <code>release()</code>.</p><h3 id="release" tabindex="-1"><a class="header-anchor" href="#release" aria-hidden="true">#</a> release</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token class-name">Future</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token keyword">void</span><span class="token punctuation">&gt;</span></span> <span class="token function">release</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">async</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token comment">// usage</span>
fplayer<span class="token punctuation">.</span><span class="token function">release</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>Inside, <code>release</code> checks the current player state and decides whether it needs to call <code>stop</code> first. That means you can call <code>release</code> from any state to free the underlying resources.</p><h2 id="playback-control" tabindex="-1"><a class="header-anchor" href="#playback-control" aria-hidden="true">#</a> Playback control</h2><h3 id="setdatasource" tabindex="-1"><a class="header-anchor" href="#setdatasource" aria-hidden="true">#</a> setDataSource</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token class-name">Future</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token keyword">void</span><span class="token punctuation">&gt;</span></span> <span class="token function">setDataSource</span><span class="token punctuation">(</span>
  <span class="token class-name">String</span> path<span class="token punctuation">,</span> <span class="token punctuation">{</span>
  <span class="token class-name">Map</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">String</span><span class="token punctuation">,</span> <span class="token class-name">String</span><span class="token operator">?</span><span class="token punctuation">&gt;</span></span><span class="token operator">?</span> headers<span class="token punctuation">,</span>
  bool autoPlay <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">,</span>
  bool showCover <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token comment">/// usage</span>
<span class="token comment">/// autoPlay: true is equivalent to calling setDataSource, prepareAsync and start</span>
fplayer<span class="token punctuation">.</span><span class="token function">setDataSource</span><span class="token punctuation">(</span><span class="token string-literal"><span class="token string">&quot;http://samplevideo.com/sample.flv&quot;</span></span><span class="token punctuation">,</span> autoPlay<span class="token punctuation">:</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">///</span>
<span class="token comment">/// Set a local asset as the media source.</span>
<span class="token comment">/// Declare the asset in pubspec.yml:</span>
<span class="token comment">///   assets:</span>
<span class="token comment">///     - assets/butterfly.mp4</span>
<span class="token comment">///</span>
<span class="token comment">/// The scheme is \`asset\`; \`://\` separates the scheme and \`/\` starts the path.</span>
fplayer<span class="token punctuation">.</span><span class="token function">setDataSource</span><span class="token punctuation">(</span><span class="token string-literal"><span class="token string">&quot;asset:///assets/butterfly.mp4&quot;</span></span><span class="token punctuation">,</span> autoPlay<span class="token punctuation">:</span> <span class="token boolean">true</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Sets the media source. The call works out the resource type itself, whether that&#39;s a network stream, a local file or something else.<br> Setting the optional <code>autoPlay</code> flag to true calls <code>prepareAsync</code> and <code>start</code> after the source is set, so playback begins on its own. It&#39;s equivalent to:</p><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token keyword">await</span> <span class="token function">setDataSource</span><span class="token punctuation">(</span>url<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">await</span> <span class="token function">setOption</span><span class="token punctuation">(</span><span class="token class-name">FOption</span><span class="token punctuation">.</span>playerCategory<span class="token punctuation">,</span> <span class="token string-literal"><span class="token string">&quot;start-on-prepared&quot;</span></span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">await</span> <span class="token function">prepareAsync</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Setting the optional <code>showCover</code> flag to true makes the player render the first video frame once it finishes parsing, then pause. The player keeps loading data into its buffers while paused. It&#39;s equivalent to:</p><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token keyword">await</span> <span class="token function">setDataSource</span><span class="token punctuation">(</span>url<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">await</span> <span class="token function">setOption</span><span class="token punctuation">(</span><span class="token class-name">FOption</span><span class="token punctuation">.</span>playerCategory<span class="token punctuation">,</span> <span class="token string-literal"><span class="token string">&quot;cover-after-prepared&quot;</span></span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">await</span> <span class="token function">prepareAsync</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="prepareasync" tabindex="-1"><a class="header-anchor" href="#prepareasync" aria-hidden="true">#</a> prepareAsync</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token class-name">Future</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token keyword">void</span><span class="token punctuation">&gt;</span></span> <span class="token function">prepareAsync</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">async</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token comment">// usage</span>
fplayer<span class="token punctuation">.</span><span class="token function">prepareAsync</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>Kicks the player into action: it spins up its resources, parses the media and gets ready to play. When the call returns, the player is in <code>asyncPreparing</code>; after preparation completes it moves to <code>prepared</code>. You must call <code>setDataSource</code> before this.</p><h3 id="start" tabindex="-1"><a class="header-anchor" href="#start" aria-hidden="true">#</a> start</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token class-name">Future</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token keyword">void</span><span class="token punctuation">&gt;</span></span> <span class="token function">start</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">async</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token comment">// usage</span>
fplayer<span class="token punctuation">.</span><span class="token function">start</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>Starts playback.</p><h3 id="pause" tabindex="-1"><a class="header-anchor" href="#pause" aria-hidden="true">#</a> pause</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token class-name">Future</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token keyword">void</span><span class="token punctuation">&gt;</span></span> <span class="token function">pause</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">async</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token comment">// usage</span>
fplayer<span class="token punctuation">.</span><span class="token function">pause</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>Pauses the player.</p><h3 id="stop" tabindex="-1"><a class="header-anchor" href="#stop" aria-hidden="true">#</a> stop</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token class-name">Future</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token keyword">void</span><span class="token punctuation">&gt;</span></span> <span class="token function">stop</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">async</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token comment">// usage</span>
fplayer<span class="token punctuation">.</span><span class="token function">stop</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>Stops playback. After <code>stop</code> you can&#39;t return to playing by calling <code>start</code> directly.</p><h3 id="reset" tabindex="-1"><a class="header-anchor" href="#reset" aria-hidden="true">#</a> reset</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token class-name">Future</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token keyword">void</span><span class="token punctuation">&gt;</span></span> <span class="token function">reset</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">async</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token comment">// usage</span>
fplayer<span class="token punctuation">.</span><span class="token function">reset</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>Resets the player to <code>idle</code>, after which you can call <code>setDataSource</code> again.</p><h3 id="seekto" tabindex="-1"><a class="header-anchor" href="#seekto" aria-hidden="true">#</a> seekTo</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token class-name">Future</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token keyword">void</span><span class="token punctuation">&gt;</span></span> <span class="token function">seekTo</span><span class="token punctuation">(</span>int msec<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token comment">// usage</span>
fplayer<span class="token punctuation">.</span><span class="token function">seekTo</span><span class="token punctuation">(</span><span class="token number">3000</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>Moves playback to a new position. The argument is in milliseconds and must be 0 or greater. Only callable from a playable state.</p><p><strong>Every playback control method is async. When you need to chain several of them, wait on each one with <code>await</code> or <code>Future.then()</code>. Calling the next method before the previous one finishes can leave the player in the wrong state.</strong></p><h2 id="other-methods" tabindex="-1"><a class="header-anchor" href="#other-methods" aria-hidden="true">#</a> Other methods</h2><h3 id="setvolume" tabindex="-1"><a class="header-anchor" href="#setvolume" aria-hidden="true">#</a> setVolume</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token class-name">Future</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token keyword">void</span><span class="token punctuation">&gt;</span></span> <span class="token function">setVolume</span><span class="token punctuation">(</span>double volume<span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code>fplayer<span class="token punctuation">.</span><span class="token function">setVolume</span><span class="token punctuation">(</span><span class="token number">0.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Volume ranges from 0.0 to 1.0. Anything outside that range returns a parameter error.</p><h3 id="setloop" tabindex="-1"><a class="header-anchor" href="#setloop" aria-hidden="true">#</a> setLoop</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token class-name">Future</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token keyword">void</span><span class="token punctuation">&gt;</span></span> <span class="token function">setLoop</span><span class="token punctuation">(</span>int loopCount<span class="token punctuation">)</span> <span class="token keyword">async</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code>fplayer<span class="token punctuation">.</span><span class="token function">setLoop</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>The default loop count is 1, meaning no looping. Set it to 0 to loop forever.</p><h3 id="setspeed" tabindex="-1"><a class="header-anchor" href="#setspeed" aria-hidden="true">#</a> setSpeed</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token class-name">Future</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token keyword">void</span><span class="token punctuation">&gt;</span></span> <span class="token function">setSpeed</span><span class="token punctuation">(</span>double speed<span class="token punctuation">)</span> <span class="token keyword">async</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code>fplayer<span class="token punctuation">.</span><span class="token function">setSpeed</span><span class="token punctuation">(</span><span class="token number">1.5</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Don&#39;t push the rate too far. Pick a multiplier that feels right for the content you&#39;re playing.</p><h2 id="audio-tracks" tabindex="-1"><a class="header-anchor" href="#audio-tracks" aria-hidden="true">#</a> Audio tracks</h2><p>Once the player is prepared, call <code>getAudioTracks</code> for the track list of the current media, then <code>setAudioTrack</code> to switch. Works on Android, iOS, macOS, Windows and OpenHarmony.</p><h3 id="faudiotrack" tabindex="-1"><a class="header-anchor" href="#faudiotrack" aria-hidden="true">#</a> FAudioTrack</h3><table><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>index</code></td><td><code>int</code></td><td>Stream index of the track, used when switching</td></tr><tr><td><code>language</code></td><td><code>String?</code></td><td>Track language</td></tr><tr><td><code>codec</code></td><td><code>String?</code></td><td>Short codec name, for example <code>aac</code></td></tr><tr><td><code>codecLongName</code></td><td><code>String?</code></td><td>Full codec name</td></tr><tr><td><code>sampleRate</code></td><td><code>int?</code></td><td>Sample rate in Hz</td></tr><tr><td><code>channelLayout</code></td><td><code>int?</code></td><td>FFmpeg channel layout mask</td></tr><tr><td><code>selected</code></td><td><code>bool</code></td><td>Whether this is the currently selected track</td></tr></tbody></table><h3 id="getaudiotracks" tabindex="-1"><a class="header-anchor" href="#getaudiotracks" aria-hidden="true">#</a> getAudioTracks</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token class-name">Future</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">List</span><span class="token punctuation">&lt;</span><span class="token class-name">FAudioTrack</span><span class="token punctuation">&gt;</span><span class="token punctuation">&gt;</span></span> <span class="token function">getAudioTracks</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">async</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token keyword">final</span> tracks <span class="token operator">=</span> <span class="token keyword">await</span> fplayer<span class="token punctuation">.</span><span class="token function">getAudioTracks</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">final</span> track <span class="token keyword">in</span> tracks<span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token function">print</span><span class="token punctuation">(</span><span class="token string-literal"><span class="token string">&#39;</span><span class="token interpolation"><span class="token punctuation">\${</span><span class="token expression">track<span class="token punctuation">.</span>index</span><span class="token punctuation">}</span></span><span class="token string"> </span><span class="token interpolation"><span class="token punctuation">\${</span><span class="token expression">track<span class="token punctuation">.</span>language</span><span class="token punctuation">}</span></span><span class="token string"> </span><span class="token interpolation"><span class="token punctuation">\${</span><span class="token expression">track<span class="token punctuation">.</span>codec</span><span class="token punctuation">}</span></span><span class="token string"> </span><span class="token interpolation"><span class="token punctuation">\${</span><span class="token expression">track<span class="token punctuation">.</span>selected</span><span class="token punctuation">}</span></span><span class="token string">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Returns the audio tracks of the current media. You get an empty list when the player hasn&#39;t finished preparing or the media has no audio tracks.</p><h3 id="setaudiotrack" tabindex="-1"><a class="header-anchor" href="#setaudiotrack" aria-hidden="true">#</a> setAudioTrack</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token class-name">Future</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token keyword">void</span><span class="token punctuation">&gt;</span></span> <span class="token function">setAudioTrack</span><span class="token punctuation">(</span><span class="token class-name">FAudioTrack</span> track<span class="token punctuation">)</span> <span class="token keyword">async</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token keyword">final</span> tracks <span class="token operator">=</span> <span class="token keyword">await</span> fplayer<span class="token punctuation">.</span><span class="token function">getAudioTracks</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span>tracks<span class="token punctuation">.</span>isNotEmpty<span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">await</span> fplayer<span class="token punctuation">.</span><span class="token function">setAudioTrack</span><span class="token punctuation">(</span>tracks<span class="token punctuation">.</span>first<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>track.index</code> must be one of the indexes returned by <code>getAudioTracks</code>. After switching, call <code>getAudioTracks</code> again to confirm the <code>selected</code> flag moved where you expected.</p><h2 id="subtitles" tabindex="-1"><a class="header-anchor" href="#subtitles" aria-hidden="true">#</a> Subtitles</h2><p>Subtitle tracks follow the same discovery and switching flow as audio tracks, and the player decodes subtitles by default. Works on Android, iOS, macOS, Windows and OpenHarmony. <code>FView</code> draws the current subtitle at the bottom of the video by default; pass <code>showSubtitles: false</code> to turn the built-in subtitle layer off.</p><h3 id="fsubtitletrack" tabindex="-1"><a class="header-anchor" href="#fsubtitletrack" aria-hidden="true">#</a> FSubtitleTrack</h3><table><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>index</code></td><td><code>int</code></td><td>Stream index of the subtitle track, used when switching</td></tr><tr><td><code>language</code></td><td><code>String?</code></td><td>Subtitle language</td></tr><tr><td><code>codec</code></td><td><code>String?</code></td><td>Short codec name, for example <code>subrip</code></td></tr><tr><td><code>codecLongName</code></td><td><code>String?</code></td><td>Full codec name</td></tr><tr><td><code>selected</code></td><td><code>bool</code></td><td>Whether this is the currently selected subtitle track</td></tr></tbody></table><h3 id="getsubtitletracks" tabindex="-1"><a class="header-anchor" href="#getsubtitletracks" aria-hidden="true">#</a> getSubtitleTracks</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token class-name">Future</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">List</span><span class="token punctuation">&lt;</span><span class="token class-name">FSubtitleTrack</span><span class="token punctuation">&gt;</span><span class="token punctuation">&gt;</span></span> <span class="token function">getSubtitleTracks</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">async</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token keyword">final</span> tracks <span class="token operator">=</span> <span class="token keyword">await</span> fplayer<span class="token punctuation">.</span><span class="token function">getSubtitleTracks</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token keyword">final</span> track <span class="token keyword">in</span> tracks<span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token function">print</span><span class="token punctuation">(</span><span class="token string-literal"><span class="token string">&#39;</span><span class="token interpolation"><span class="token punctuation">\${</span><span class="token expression">track<span class="token punctuation">.</span>index</span><span class="token punctuation">}</span></span><span class="token string"> </span><span class="token interpolation"><span class="token punctuation">\${</span><span class="token expression">track<span class="token punctuation">.</span>language</span><span class="token punctuation">}</span></span><span class="token string"> </span><span class="token interpolation"><span class="token punctuation">\${</span><span class="token expression">track<span class="token punctuation">.</span>codec</span><span class="token punctuation">}</span></span><span class="token string"> </span><span class="token interpolation"><span class="token punctuation">\${</span><span class="token expression">track<span class="token punctuation">.</span>selected</span><span class="token punctuation">}</span></span><span class="token string">&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Returns the subtitle tracks of the current media. You get an empty list when the player hasn&#39;t finished preparing or the media has no subtitle tracks.</p><h3 id="setsubtitletrack" tabindex="-1"><a class="header-anchor" href="#setsubtitletrack" aria-hidden="true">#</a> setSubtitleTrack</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token class-name">Future</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token keyword">void</span><span class="token punctuation">&gt;</span></span> <span class="token function">setSubtitleTrack</span><span class="token punctuation">(</span><span class="token class-name">FSubtitleTrack</span><span class="token operator">?</span> track<span class="token punctuation">)</span> <span class="token keyword">async</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token keyword">final</span> tracks <span class="token operator">=</span> <span class="token keyword">await</span> fplayer<span class="token punctuation">.</span><span class="token function">getSubtitleTracks</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token keyword">if</span> <span class="token punctuation">(</span>tracks<span class="token punctuation">.</span>isNotEmpty<span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token keyword">await</span> fplayer<span class="token punctuation">.</span><span class="token function">setSubtitleTrack</span><span class="token punctuation">(</span>tracks<span class="token punctuation">.</span>first<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
<span class="token comment">// Turn subtitles off</span>
<span class="token keyword">await</span> fplayer<span class="token punctuation">.</span><span class="token function">setSubtitleTrack</span><span class="token punctuation">(</span><span class="token keyword">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>track.index</code> must be one of the indexes returned by <code>getSubtitleTracks</code>. Passing <code>null</code> clears the current subtitle selection.</p><h3 id="subtitle-text" tabindex="-1"><a class="header-anchor" href="#subtitle-text" aria-hidden="true">#</a> Subtitle text</h3><p><code>FView</code> displays subtitle text by default. If you&#39;re building your own subtitle layer, listen to <code>onSubtitleTextUpdate</code> or read <code>subtitleText</code>:</p><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token keyword">final</span> subscription <span class="token operator">=</span> fplayer<span class="token punctuation">.</span>onSubtitleTextUpdate<span class="token punctuation">.</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token punctuation">(</span>text<span class="token punctuation">)</span> <span class="token punctuation">{</span>
  <span class="token function">print</span><span class="token punctuation">(</span>text <span class="token operator">?</span><span class="token operator">?</span> <span class="token string-literal"><span class="token string">&#39;&#39;</span></span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>An empty <code>text</code> in the event means the current subtitle has ended, so hide your subtitle layer.</p><h3 id="enterfullscreen" tabindex="-1"><a class="header-anchor" href="#enterfullscreen" aria-hidden="true">#</a> enterFullScreen</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token keyword">void</span> <span class="token function">enterFullScreen</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>These two methods only flip a flag on the player. The actual fullscreen UI lives in <code>FView</code>, which watches that flag and reworks its layout when it changes.</p><h3 id="exitfullscreen" tabindex="-1"><a class="header-anchor" href="#exitfullscreen" aria-hidden="true">#</a> exitFullScreen</h3><div class="language-dart line-numbers-mode" data-ext="dart"><pre class="language-dart"><code><span class="token keyword">void</span> <span class="token function">exitFullScreen</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div>`,87),p=[c];function o(i,l){return n(),s("div",null,p)}const r=a(t,[["render",o],["__file","api.html.vue"]]);export{r as default};
